@dataclass(frozen=True)
class ChatCompletion:
    """Provider text plus finish metadata. Existing chat helpers still return str."""

    text: str
    truncated: bool = False
    finish_reason: str | None = None
    provider: str = "unknown"
    fallback_used: bool = False


def _remember_completion(result: "ChatCompletion") -> "ChatCompletion":
    _completion_tls.last = result
    return result


